using System.Windows.Media;

namespace RhinoGuire.UI.Controls;

/// <summary>
/// Lucide icon geometry (ISC licence, <c>Icons/lucide/LICENSE</c>), on Lucide's 24 x 24 grid.
/// The path data is generated by <c>tools/build_lucide_icons.py</c> into <c>LucideIcons.g.cs</c>.
/// </summary>
public static partial class LucideIcons
{
    /// <summary>Lucide's design grid: every icon is drawn in a 24 x 24 box.</summary>
    public const double GridSize = 24.0;

    private static readonly Geometry?[] Cache = new Geometry?[PathData.Length];

    /// <summary>Frozen geometry for <paramref name="kind"/> on the 24 x 24 grid (empty for <see cref="IconKind.None"/>).</summary>
    public static Geometry Get(IconKind kind)
    {
        int i = (int)kind;
        if (i <= 0 || i >= PathData.Length) return Geometry.Empty;
        var cached = Cache[i];
        if (cached != null) return cached;
        var geometry = Geometry.Parse(PathData[i]);
        geometry.Freeze();
        Cache[i] = geometry;
        return geometry;
    }

    /// <summary>Raw path markup for <paramref name="kind"/>, for use in a XAML <c>Path.Data</c>.</summary>
    public static string GetPathData(IconKind kind)
    {
        int i = (int)kind;
        return i > 0 && i < PathData.Length ? PathData[i] : "";
    }
}
